import { useEffect, useState } from 'react';
import {
  FocusContext,
  setFocus,
  useFocusable,
} from '@noriginmedia/norigin-spatial-navigation';
import type { StoredList } from '@mfp/core';
import { FocusButton } from '../components/FocusButton.js';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useLists } from '../state/lists.js';
import { useToast } from '../components/Toast.js';
import { Onboarding } from './Onboarding.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar, gapWrapClass, gapWrapInnerClass } from '../theme/gap.js';

/**
 * Gerenciar listas Xtream (RF-49): trocar a ativa, **editar** servidor/usuário/
 * senha de uma já cadastrada, remover, ou adicionar. Antes disso o único jeito
 * de corrigir uma credencial errada era pela tela de conta expirada.
 *
 * Editar e adicionar reaproveitam o `Onboarding` — mesmo formulário, mesma
 * validação `authenticate()` antes de gravar, mesma senha só no secure storage.
 */
type Modo =
  { tela: 'lista' } | { tela: 'adicionar' } | { tela: 'editar'; lista: StoredList };

export function ManageLists() {
  const [modo, setModo] = useState<Modo>({ tela: 'lista' });

  if (modo.tela === 'adicionar') {
    return (
      <Onboarding
        onDone={() => setModo({ tela: 'lista' })}
        onCancel={() => setModo({ tela: 'lista' })}
      />
    );
  }
  if (modo.tela === 'editar') {
    return (
      <Onboarding
        listId={modo.lista.id}
        initial={{ serverUrl: modo.lista.serverUrl, username: modo.lista.username }}
        onDone={() => setModo({ tela: 'lista' })}
        onCancel={() => setModo({ tela: 'lista' })}
      />
    );
  }
  return (
    <Lista
      onAdicionar={() => setModo({ tela: 'adicionar' })}
      onEditar={(l) => setModo({ tela: 'editar', lista: l })}
    />
  );
}

function Lista({
  onAdicionar,
  onEditar,
}: Readonly<{ onAdicionar: () => void; onEditar: (l: StoredList) => void }>) {
  const rt = useRuntime();
  const lists = useLists((s) => s.lists);
  const activeListId = useLists((s) => s.activeListId);
  const setActive = useLists((s) => s.setActive);
  const removeList = useLists((s) => s.removeList);
  const mostrar = useToast((s) => s.show);
  const [confirmarRemover, setConfirmarRemover] = useState<string | null>(null);

  const { ref, focusKey } = useFocusable({
    focusKey: 'lists-manage',
    trackChildren: true,
  });

  useEffect(() => {
    setFocus(lists[0] ? `list-${lists[0].id}-edit` : 'lists-add');
  }, [lists]);

  return (
    <FocusContext.Provider value={focusKey}>
      <div
        ref={ref}
        className={gapColClass}
        style={{
          maxWidth: '48rem',
          display: 'flex',
          flexDirection: 'column',
          ...gapVar('1rem'),
        }}
      >
        <h1>{t('lists.title')}</h1>

        {lists.map((l) => {
          const ativa = l.id === activeListId;
          return (
            <div
              key={l.id}
              className={gapColClass}
              style={{
                background: 'var(--bg-panel)',
                borderRadius: 'var(--radius-md)',
                padding: '1rem',
                borderLeft: ativa ? '3px solid var(--accent)' : '3px solid transparent',
                display: 'flex',
                flexDirection: 'column',
                ...gapVar('0.6rem'),
              }}
            >
              <div>
                <strong>{l.name}</strong>
                {ativa && (
                  <span style={{ color: 'var(--accent)', marginLeft: '0.6rem' }}>
                    {t('lists.active')}
                  </span>
                )}
                <div
                  style={{
                    fontSize: 'var(--fs-meta)',
                    color: 'var(--text-secondary)',
                  }}
                >
                  {l.serverUrl} · {l.username}
                </div>
              </div>

              {confirmarRemover === l.id ? (
                <div
                  className={gapRowClass}
                  style={{ display: 'flex', alignItems: 'center', ...gapVar('0.6rem') }}
                >
                  <span>{t('lists.removeConfirm')}</span>
                  <FocusButton
                    primary
                    focusKey={`list-${l.id}-remove-yes`}
                    onPress={() => {
                      void removeList(rt, l.id).then(() => {
                        mostrar(t('lists.removed', { name: l.name }));
                        setConfirmarRemover(null);
                      });
                    }}
                  >
                    {t('common.confirm')}
                  </FocusButton>
                  <FocusButton
                    focusKey={`list-${l.id}-remove-no`}
                    onPress={() => setConfirmarRemover(null)}
                  >
                    {t('common.cancel')}
                  </FocusButton>
                </div>
              ) : (
                <div className={gapWrapClass}>
                  <div
                    className={gapWrapInnerClass}
                    style={{ display: 'flex', flexWrap: 'wrap', ...gapVar('0.6rem') }}
                  >
                  {!ativa && (
                    <FocusButton
                      focusKey={`list-${l.id}-activate`}
                      onPress={() => {
                        void setActive(rt, l.id).then(() =>
                          mostrar(t('lists.switched', { name: l.name })),
                        );
                      }}
                    >
                      {t('lists.makeActive')}
                    </FocusButton>
                  )}
                  <FocusButton focusKey={`list-${l.id}-edit`} onPress={() => onEditar(l)}>
                    {t('lists.edit')}
                  </FocusButton>
                  <FocusButton
                    focusKey={`list-${l.id}-remove`}
                    disabled={lists.length === 1}
                    onPress={() => setConfirmarRemover(l.id)}
                  >
                    {t('lists.remove')}
                  </FocusButton>
                  </div>
                </div>
              )}
            </div>
          );
        })}

        <FocusButton primary focusKey="lists-add" onPress={onAdicionar}>
          {t('lists.add')}
        </FocusButton>

        {lists.length === 1 && (
          <p style={{ fontSize: 'var(--fs-meta)', color: 'var(--text-secondary)' }}>
            {t('lists.lastOne')}
          </p>
        )}
      </div>
    </FocusContext.Provider>
  );
}
